// sotc: offline test of the SOTC_TRACE recorder (gpu/shim/sotc_trace.cpp), no game needed.
// Build (CLANG64, from the repo root; miniz_export.h is generated by the CMake build, so it comes
// from out/gpu/third_party/miniz):
//   clang++ -std=c++20 -O1 -Igpu/shadps4 -Igpu/third_party/miniz -Iout/gpu/third_party/miniz \
//     tools/sotc_trace_test.cpp gpu/shim/sotc_trace.cpp gpu/third_party/miniz/*.c \
//     -o out/sotc_trace_test.exe -lpthread
// (the four miniz sources: miniz.c, miniz_tdef.c, miniz_tinfl.c, miniz_zip.c)
// Run mode 1: SOTC_TRACE=1 SOTC_TRACE_DIR=out/trace_test out/sotc_trace_test.exe
// Run mode 2: SOTC_TRACE=2 SOTC_TRACE_DIR=out/trace_test out/sotc_trace_test.exe
// Without SOTC_TRACE_DIR the files go to user/trace, as in the game.
// Mode 1: four threads record spans while frames end every 33 ms; frame 10 takes 120 ms. One
// frameNNNNNN_XXms.sotctrace must hold the slow frame, RequestDump must give manual001.sotctrace,
// and both must contain the Mark, SetSegment, Counter, Message and fiber names.
// Mode 2: session.sotctrace must grow while the workload runs.
// The test reads the chunks back (inflating them with miniz) and prints the file paths, so the
// Python loader can be run on them.
#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <functional>
#include <iterator>
#include <set>
#include <string>
#include <thread>
#include <vector>

#include "miniz.h"
#include "video_core/sotc_stats.h"
#include "video_core/sotc_trace.h"

namespace fs = std::filesystem;
using namespace std::chrono_literals;

namespace {

int g_failures = 0;

void Check(bool ok, const char* what) {
    std::printf("%s %s\n", ok ? "ok  " : "FAIL", what);
    if (!ok) {
        ++g_failures;
    }
}

// Polls ok() every 50 ms for up to timeout_ms.
bool WaitFor(const std::function<bool()>& ok, int timeout_ms) {
    for (int waited = 0; waited <= timeout_ms; waited += 50) {
        if (ok()) {
            return true;
        }
        std::this_thread::sleep_for(50ms);
    }
    return false;
}

SotcTrace::ZoneSite kZone{"test zone", __FILE__, __LINE__};

// Four threads record spans (thread 1 is the draw thread, merged with OpBatch) while the main
// thread ends `frames` frames of 33 ms. Frame `slow_frame` (0: none) takes 120 ms.
void RunWorkload(uint64_t frames, uint64_t slow_frame) {
    std::atomic<bool> stop{false};
    std::vector<std::thread> threads;
    for (int t = 0; t < 4; ++t) {
        threads.emplace_back([&, t] {
            if (t == 1) {
                SotcStats::tl_role = SotcStats::RoleDraw;
            }
            SotcTrace::OpBatch batch;
            uint64_t n = 0;
            while (!stop.load()) {
                const uint64_t t0 = SotcTrace::Now();
                if (t == 1) {
                    while (SotcTrace::Now() - t0 < (n % 100 == 0 ? 80000u : 3000u)) {
                    }
                } else {
                    std::this_thread::sleep_for(std::chrono::microseconds(500));
                }
                const uint64_t t1 = SotcTrace::Now();
                if (t == 1) {
                    batch.Note("draw", t0, t1, n);
                } else {
                    SotcTrace::Span("evf wait", t0, t1, n, 0x1000 + 0x101ae4);
                }
                ++n;
            }
            batch.Flush();
        });
    }
    const uint32_t q = SotcTrace::RegisterQueue("GPU: test queue");
    uint64_t prev = SotcTrace::Now();
    for (uint64_t frame = 1; frame <= frames; ++frame) {
        if (frame == 1) {
            SotcTrace::SetSegment("route A", 1);
        }
        if (slow_frame && frame == slow_frame - 1) {
            SotcTrace::Mark("test mark");
            SotcTrace::Counter("test counter", 42);
        }
        if (frame == frames) {
            const char text[] = "hello msg";
            SotcTrace::Message(text, sizeof(text) - 1);
        }
        SotcTrace::FlipMark(frame);
        SotcTrace::Submitted(q, frame, SotcTrace::Now());
        {
            SotcTrace::ZoneScope zone(&kZone);
            SotcTrace::FiberEnter("fiber task");
            std::this_thread::sleep_for(std::chrono::milliseconds(frame == slow_frame ? 120 : 33));
            SotcTrace::FiberExit();
        }
        const uint64_t now = SotcTrace::Now();
        SotcTrace::Completed(q, frame, frame, now);
        SotcTrace::FrameEnd(frame, prev, now);
        prev = now;
    }
    stop = true;
    for (auto& th : threads) {
        th.join();
    }
}

struct Chunk {
    uint32_t type = 0;
    std::string payload;
};

// Reads the chunks of a .sotctrace file, inflating the compressed ones. False when the magic is
// wrong or a compressed chunk does not inflate.
bool ReadChunks(const fs::path& path, std::vector<Chunk>& out) {
    std::ifstream in(path, std::ios::binary);
    if (!in) {
        return false;
    }
    const std::string bytes((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    if (bytes.size() < 8 || std::memcmp(bytes.data(), "SOTCTRC\x01", 8) != 0) {
        return false;
    }
    size_t pos = 8;
    while (pos + 16 <= bytes.size()) {
        uint32_t hdr[4];
        std::memcpy(hdr, bytes.data() + pos, sizeof(hdr));
        const uint32_t type = hdr[0], flags = hdr[1], stored = hdr[2], raw = hdr[3];
        pos += 16;
        if (pos + stored > bytes.size()) {
            break; // a truncated last chunk is ignored, as the format says
        }
        Chunk c;
        c.type = type;
        if (flags & 1) {
            c.payload.resize(raw);
            mz_ulong len = raw;
            if (mz_uncompress(reinterpret_cast<unsigned char*>(c.payload.data()), &len,
                              reinterpret_cast<const unsigned char*>(bytes.data() + pos),
                              stored) != MZ_OK ||
                len != raw) {
                return false;
            }
        } else {
            c.payload.assign(bytes.data() + pos, stored);
        }
        pos += stored;
        out.push_back(std::move(c));
        if (type == 0xFFFFFFFFu) {
            break;
        }
    }
    return true;
}

struct Summary {
    std::set<uint32_t> types;
    std::string names;   // every NAMES payload, concatenated
    std::string threads; // every THREADS payload, concatenated
    uint64_t events = 0;
};

Summary Summarize(const std::vector<Chunk>& chunks) {
    Summary s;
    for (const Chunk& c : chunks) {
        s.types.insert(c.type);
        if (c.type == 2) {
            s.threads += c.payload;
        } else if (c.type == 3) {
            s.names += c.payload;
        } else if (c.type == 4 && c.payload.size() >= 8) {
            uint32_t count = 0;
            std::memcpy(&count, c.payload.data() + 4, 4);
            s.events += count;
        }
    }
    return s;
}

// The newest session folder under base (names are YYYYmmdd-HHMMSS, so the largest sorts last).
fs::path NewestSession(const fs::path& base) {
    fs::path best;
    std::error_code ec;
    for (auto it = fs::directory_iterator(base, ec); !ec && it != fs::directory_iterator(); ++it) {
        if (it->is_directory(ec) && (best.empty() || it->path().filename() > best.filename())) {
            best = it->path();
        }
    }
    return best;
}

bool Has(const std::string& haystack, const char* needle) {
    return haystack.find(needle) != std::string::npos;
}

int RunFlight(const fs::path& base) {
    // Registered before the workload: the slow frame's dump is written during the post window.
    SotcTrace::RegisterChunkProvider(0x100, [] () -> std::string { return std::string(400, 'x'); });
    RunWorkload(20, 10);
    // Extra track, chunk provider and thread snapshot (the sampler and GPU timeline use these).
    const uint32_t track = SotcTrace::NewTrack("test track", "gpu", 0);
    const uint64_t now = SotcTrace::Now();
    SotcTrace::PushEventOn(track, SotcTrace::EvSpan, "track span", now - 1'000'000, now);
    bool track_listed = false;
    for (const auto& th : SotcTrace::Threads()) {
        track_listed = track_listed || th.name == "test track";
    }
    Check(track != 0 && !track_listed, "NewTrack works and Threads() leaves extra tracks out");
    Check(SotcTrace::RequestDump("unit test"), "RequestDump queued a manual dump");
    const bool written = WaitFor(
        [] { return SotcTrace::LastDump().path.find("manual001") != std::string::npos; }, 10000);
    Check(written, "manual001.sotctrace written by the writer");

    const fs::path session = NewestSession(base);
    fs::path slow, manual;
    std::error_code ec;
    for (auto it = fs::directory_iterator(session, ec); !ec && it != fs::directory_iterator(); ++it) {
        const std::string name = it->path().filename().string();
        if (name.rfind("frame", 0) == 0 && name.ends_with(".sotctrace")) {
            slow = it->path();
        } else if (name == "manual001.sotctrace") {
            manual = it->path();
        }
    }
    Check(!slow.empty(), "frameNNNNNN_XXms.sotctrace written for the slow frame");
    Check(!manual.empty(), "manual001.sotctrace in the session folder");

    for (const fs::path& file : {slow, manual}) {
        if (file.empty()) {
            continue;
        }
        std::printf("file: %s\n", file.string().c_str());
        std::vector<Chunk> chunks;
        const bool read = ReadChunks(file, chunks);
        const Summary s = Summarize(chunks);
        Check(read, "chunks read back (magic, inflate)");
        Check(s.types.count(1) && s.types.count(2) && s.types.count(4) && s.types.count(5) &&
                  s.types.count(0xFFFFFFFFu),
              "META, THREADS, EVENTS, ZONE_STATS and END present");
        Check(s.events > 0, "EVENTS hold events");
        Check(s.types.count(0x100), "chunk provider output written as its chunk");
        Check(Has(s.names, "\"route A\""), "SetSegment name in NAMES (frame events)");
        Check(Has(s.names, "\"fiber task\""), "FiberEnter/FiberExit span in NAMES");
    }
    if (!slow.empty()) {
        std::vector<Chunk> chunks;
        ReadChunks(slow, chunks);
        const std::string names = Summarize(chunks).names;
        Check(Has(names, "\"test mark\""), "Mark in the slow frame's window");
        Check(Has(names, "\"test counter\""), "Counter in the slow frame's window");
    }
    if (!manual.empty()) {
        std::vector<Chunk> chunks;
        ReadChunks(manual, chunks);
        const std::string names = Summarize(chunks).names;
        Check(Has(names, "\"hello msg\""), "Message in the manual dump's window");
        Check(Has(names, "\"track span\""), "PushEventOn span in the manual dump");
        Check(Has(Summarize(chunks).threads, "\"name\":\"test track\",\"kind\":\"gpu\""),
              "extra track listed in THREADS with its kind");
    }
    std::printf("self-stats: %s\n", SotcTrace::StatsJson().c_str());
    return g_failures ? 1 : 0;
}

int RunStream(const fs::path& base) {
    RunWorkload(30, 0); // about 1 s
    const auto stream_file = [&base] { return NewestSession(base) / "session.sotctrace"; };
    const bool exists = WaitFor([&] { return fs::exists(stream_file()); }, 5000);
    Check(exists, "session.sotctrace created");
    if (!exists) {
        return 1;
    }
    const uint64_t before = fs::file_size(stream_file());
    RunWorkload(30, 0); // about 1 s more
    const uint64_t after = fs::file_size(stream_file());
    Check(after > before, "session.sotctrace grows while the workload runs");
    Check(SotcTrace::RequestDump("unit test"), "RequestDump writes a mark in mode 2");
    std::printf("file: %s (%llu -> %llu bytes; END is written at exit)\n",
                stream_file().string().c_str(), static_cast<unsigned long long>(before),
                static_cast<unsigned long long>(after));
    std::printf("self-stats: %s\n", SotcTrace::StatsJson().c_str());
    return g_failures ? 1 : 0;
}

} // namespace

int main() {
    if (!SotcTrace::kOn) {
        std::fprintf(stderr, "set SOTC_TRACE=1 (flight recorder) or SOTC_TRACE=2 (stream)\n");
        return 2;
    }
    const char* env = std::getenv("SOTC_TRACE_DIR");
    const fs::path base = (env && *env) ? fs::path(env) : fs::path("user/trace");
    SotcTrace::SetImage(0x1000, 0x2000000);
    return SotcTrace::kMode == 2 ? RunStream(base) : RunFlight(base);
}
